package in.gcet.sis.ui;
import in.gcet.sis.dao.PortalDao;import in.gcet.sis.model.*;import in.gcet.sis.service.DashboardService;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.util.List;
public class StudentFrame extends JFrame {
 private final User user;private final PortalDao dao=new PortalDao();private final JTable skills=table(),internships=table(),applications=table();private final JPanel metrics=new JPanel(new GridLayout(1,6,10,10));
 public StudentFrame(User u){user=u;setTitle("Student Workspace");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1180,760);setLocationRelativeTo(null);JPanel shell=new JPanel(new BorderLayout(14,14));shell.setBorder(BorderFactory.createEmptyBorder(20,22,20,22));shell.setBackground(Theme.BG);JLabel title=new JLabel("STUDENT WORKSPACE   /   "+u.fullName());title.setForeground(Theme.TEXT);title.setFont(new Font("Segoe UI",Font.BOLD,23));shell.add(title,BorderLayout.NORTH);
  JPanel centre=new JPanel(new BorderLayout(12,12));centre.setOpaque(false);metrics.setOpaque(false);centre.add(metrics,BorderLayout.NORTH);JTabbedPane tabs=new JTabbedPane();tabs.addTab("My skills",tablePanel(skills,new String[]{"ID","Skill","Category","Proficiency","Years"}));tabs.addTab("Explore internships",tablePanel(internships,new String[]{"ID","Role","Company","Location","Duration","Stipend","Deadline","Skills","Description"}));tabs.addTab("My applications",tablePanel(applications,new String[]{"ID","Role","Company","Status","Admin feedback","Applied"}));centre.add(tabs,BorderLayout.CENTER);shell.add(centre,BorderLayout.CENTER);
  JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);JButton add=button("ADD / UPDATE SKILL"),remove=button("REMOVE SKILL"),apply=button("APPLY SELECTED"),refresh=button("REFRESH ALL"),logout=button("LOG OUT");for(JButton b:new JButton[]{add,remove,apply,refresh,logout})actions.add(b);shell.add(actions,BorderLayout.SOUTH);add.addActionListener(e->addSkill());remove.addActionListener(e->removeSkill());apply.addActionListener(e->apply());refresh.addActionListener(e->loadAll());logout.addActionListener(e->{new LoginFrame().setVisible(true);dispose();});add(shell);loadAll();
 }
 private JTable table(){JTable t=new JTable();t.setRowHeight(26);t.setAutoCreateRowSorter(true);return t;}
 private JPanel tablePanel(JTable t,String[] cols){JPanel p=new JPanel(new BorderLayout());p.setBackground(Theme.BG);t.setModel(new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}});p.add(new JScrollPane(t));return p;}
 private JButton button(String s){JButton b=new JButton(s);Theme.button(b);return b;}private void rows(JTable t,List<Object[]> data){DefaultTableModel m=(DefaultTableModel)t.getModel();m.setRowCount(0);for(Object[] r:data)m.addRow(r);}
 private void loadAll(){new SwingWorker<Void,Void>(){List<Object[]> sk,in,ap;DashboardStats stats;protected Void doInBackground()throws Exception{sk=dao.skills(user.id());in=dao.internships();ap=dao.myApplications(user.id());stats=new DashboardService().load(user.id());return null;}protected void done(){try{get();rows(skills,sk);rows(internships,in);rows(applications,ap);metrics.removeAll();metric("SKILLS",stats.skills());metric("OPEN ROLES",stats.openInternships());metric("APPLICATIONS",stats.applications());metric("PENDING",stats.pending());metric("ACCEPTED",stats.accepted());metric("REJECTED",stats.rejected());metrics.revalidate();metrics.repaint();}catch(Exception e){error(e);}}}.execute();}
 private void metric(String label,long value){JPanel c=new JPanel(new BorderLayout(4,4));c.setBackground(Theme.CARD);c.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Theme.COPPER),BorderFactory.createEmptyBorder(10,12,10,12)));JLabel l=new JLabel(label),v=new JLabel(""+value);l.setForeground(Theme.MUTED);v.setForeground(Theme.TEXT);v.setFont(new Font("Segoe UI",Font.BOLD,24));c.add(l,BorderLayout.NORTH);c.add(v,BorderLayout.CENTER);metrics.add(c);}
 private void addSkill(){JTextField n=new JTextField(),c=new JTextField("Technical"),y=new JTextField("0");JComboBox<String> level=new JComboBox<>(new String[]{"BEGINNER","INTERMEDIATE","ADVANCED"});JPanel p=new JPanel(new GridLayout(0,2,6,6));for(Object[] a:new Object[][]{{"Skill",n},{"Category",c},{"Proficiency",level},{"Experience years",y}}){p.add(new JLabel((String)a[0]));p.add((Component)a[1]);}if(JOptionPane.showConfirmDialog(this,p,"Add / update skill",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;run(()->{try{dao.addSkill(user.id(),n.getText(),c.getText(),(String)level.getSelectedItem(),Double.parseDouble(y.getText()));loadAll();}catch(Exception e){throw new RuntimeException(e);}});}
 private void removeSkill(){int r=skills.getSelectedRow();if(r<0){warn("Select a skill first.");return;}long id=((Number)skills.getValueAt(skills.convertRowIndexToModel(r),0)).longValue();run(()->{try{dao.removeSkill(user.id(),id);loadAll();}catch(Exception e){throw new RuntimeException(e);}});}
 private void apply(){int r=internships.getSelectedRow();if(r<0){warn("Select an internship first.");return;}int mr=internships.convertRowIndexToModel(r);long id=((Number)internships.getValueAt(mr,0)).longValue();String title=String.valueOf(internships.getValueAt(mr,1));JTextArea letter=new JTextArea(8,36);letter.setLineWrap(true);letter.setWrapStyleWord(true);if(JOptionPane.showConfirmDialog(this,new JScrollPane(letter),"Cover letter for "+title,JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;run(()->{try{dao.apply(user.id(),id,letter.getText());loadAll();}catch(Exception e){throw new RuntimeException(e);}});}
 private void run(Runnable r){new SwingWorker<Void,Void>(){protected Void doInBackground(){r.run();return null;}protected void done(){try{get();}catch(Exception e){error(e);}}}.execute();}
 private void error(Exception e){Throwable t=e.getCause()==null?e:e.getCause();warn(t.getMessage());}private void warn(String s){JOptionPane.showMessageDialog(this,s);}
}